(async()=>{const b=Uint8Array.from(atob(''),c=>c.charCodeAt(0));const t=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text();document.getElementById('sphere-vector').innerHTML=t})().catch(()=>document.getElementById('sphere-vector').textContent='Não foi possível carregar a figura. Recarregue a página.');
